<?php

/*
 * maestro's plugin shim: Composer\Package\Package, reimplemented with
 * Composer 2.10.3's behaviour (docs/PLUGINS.md §4.5). See BasePackage for
 * how a Go-owned package mirrors maestro's; its setters change maestro's
 * package (pkg.<setter>), whose new state reaches PHP before they return.
 * Generated by hand from Composer's API; written for PHP 7.2.5 to 8.5.
 */

namespace Composer\Package;

use Composer\Package\Version\VersionParser;
use Composer\Pcre\Preg;
use Maestro\Shim\Remote;
use Maestro\Shim\Rpc;

