    public function setRequires(array $requires): void
    {
        if (isset($requires[0])) {
            $requires = $this->convertLinksToMap($requires, 'setRequires');
        }
        if (Remote::owned($this)) {
            Rpc::call('pkg.setRequires', [$this, $requires]);

            return;
        }
        $this->requires = $requires;
    }

